test('manual-only、paths过滤、取消或fake echo入口不继承旧profile；保留真实存在侧而不造head行',t=>{
 const f=legacyEntryFixture(t),ci='.github/workflows/ci.yml',original=f.git('show',f.source.base_revision+':'+ci);
 for(const edit of[d=>{d.on={workflow_dispatch:{}};},d=>{d.on.pull_request.paths=['docs/**'];},d=>{d.jobs['brain-unit'].if='cancelled()';},d=>{d.jobs['brain-unit'].steps.find(s=>s.name?.startsWith('Unit Tests')).run='echo npx vitest run';}]){
  const doc=yaml.load(original);edit(doc);writeFileSync(join(f.root,ci),yaml.dump(doc));f.source.head_revision=f.commit();f.source.changed_files=f.git('diff','--no-renames','--name-only',f.source.base_revision,f.source.head_revision).split('\n').map(path=>({path}));
  const proof=derived(f);assert.equal(proof.rows.some(r=>r.input_facts.path===f.path&&r.input_facts.source.side==='head'),false);
  assert.ok(proof.unproven.some(r=>r.path===f.path&&r.side==='head'&&r.reason==='entry_unproven'));
 }
});
